-- rule grams_in_count_unit (text_quantity): parameterized; p1 text, p2 text, p3 text, p4 text, p5 text, p6 numeric
SELECT t."parent_id", t."child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p1 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p2 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p3 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" IN (CAST(:p4 AS text), CAST(:p5 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p6 AS numeric) * x.numerator GROUP BY t."parent_id", t."child_id", t."qty_per", x.numerator, x.divisor;

-- rule grams_in_count_unit: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_grams_in_count_unit" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."numerator" NULLS FIRST, r."divisor" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT t."parent_id", t."child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(E'\\[[ \\t\\n\\r\\f\\v]*([0-9.]+)[ \\t\\n\\r\\f\\v]*g[ \\t\\n\\r\\f\\v]*(?:\\/[ \\t\\n\\r\\f\\v]*([0-9]+)[ \\t\\n\\r\\f\\v]*)?\\]' AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(E'^[0-9]+(\\.[0-9]+)?$' AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(E'^[0-9]+$' AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" IN (CAST(E'pc' AS text), CAST(E'box' AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(E'0.001' AS numeric) * x.numerator GROUP BY t."parent_id", t."child_id", t."qty_per", x.numerator, x.divisor) r;

-- example grams_in_count_unit[0]: parameterized; 30 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS text)), (CAST(:p4 AS text), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS text)), (CAST(:p10 AS text), CAST(:p11 AS numeric(18,6)), CAST(:p12 AS text))), "sxc_ex_part"("part_id", "name", "unit") AS (VALUES (CAST(:p13 AS text), CAST(:p14 AS text), CAST(:p15 AS text)), (CAST(:p16 AS text), CAST(:p17 AS text), CAST(:p18 AS text)), (CAST(:p19 AS text), CAST(:p20 AS text), CAST(:p21 AS text)), (CAST(:p22 AS text), CAST(:p23 AS text), CAST(:p24 AS text))) SELECT * FROM (SELECT t."parent_id", t."child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_ex_bom_line" t JOIN "sxc_ex_part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p25 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p26 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p27 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" IN (CAST(:p28 AS text), CAST(:p29 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p30 AS numeric) * x.numerator GROUP BY t."parent_id", t."child_id", t."qty_per", x.numerator, x.divisor) r;
